learn=[('Bound the whole agent tree', 'Each child makes model requests and can request descendants. Use independent depth, concurrency and estimated spend limits instead of assuming a short prompt bounds the work.'), ('Understand depth versus concurrency', 'Depth 1 removes child spawning from the bottom layer. Depth 2 permits a coordinator and grandchild auditor. Concurrency caps simultaneously admitted Agent children and returns native refusals when full.'), ('Handle native budget results', 'A tiny maxBudgetUsd produces error_max_budget_usd. Retain the native result before handling the SDK exception. The spend estimate includes child requests and can be crossed by an in-flight request.'), ('Preserve and extend the environment', 'Spread process.env in TypeScript options.env to preserve PATH and private model credentials. Set explicit string-valued depth and concurrency caps for each run.'), ('Control Opus 5 delegation', 'Compare a custom orchestration instruction with the claude_code preset using an explicit delegation request. Prompts steer choices; configured runtime limits enforce the admitted work.'), ('Move orchestration into Workflow', 'Use the actual Workflow tool and a reviewed JavaScript script to audit three files. Compare pipeline fan-out with serial awaits, inspect native hooks and reports, and understand how script variables keep intermediate results out of the main conversation.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3145\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, model API credit and Opus 5 access for its two comparison scenarios. Windows may need Git Bash for the SDK runtime. No GitHub token or external service is required.', 'node --version\nnpm --version'), ('Install and configure .env', 'Install pinned dependencies. Preserve any existing .env and enter your API key privately. A model key is the only credential needed.', 'cd .\\agent-sdk\\lesson45-scaling-workflows\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal running and use the five student pages. Choose one fixed scenario; inspect native result status, limit configuration and actual child cards.', 'npm start\n# http://127.0.0.1:3145'), ('Compare depth and concurrency', 'Bounded requests three service reviewers. Depth1 makes the coordinator do its own read; Depth2 permits its grandchild. Concurrency requests three background launches with a cap of one and reports refused services honestly.', 'npm run sample:env -- bounded\nnpm run sample:env -- depth1\nnpm run sample:env -- depth2\nnpm run sample:env -- concurrency'), ('Observe budget and Opus 5 behavior', 'Budget intentionally stops at a tiny SDK threshold. Preserve the native error result and observe the expected exception. Opus and Preset explicitly request the same finite audit under the same caps; neither is a latency or quality benchmark.', 'npm run sample:env -- budget\nnpm run sample:env -- opus\nnpm run sample:env -- preset'), ('Compare Workflow fan-out and serial coordination', 'Workflow executes the reviewed three-file pipeline script. Serial awaits one audit at a time. Both run the native Workflow tool, retain real task completion evidence and independently verify unchanged fixtures. The scripts use globals provided by the Workflow runtime; do not run them directly with node.', 'npm run sample:env -- workflow\nnpm run sample:env -- serial\nnpm test')]
specs=[('Choose explicit classroom limits', 'src/scaling.ts', 'export function limitsFor', 'Select depth, concurrency and estimated spend independently. This three-service teaching example uses smaller explicit caps rather than relying on runtime defaults.', 0, 1, 9), ('Build string-valued cap environment', 'src/scaling.ts', 'export function capEnvironment', 'Pass depth and Agent concurrency through env strings. Workflow has a separate concurrency setting; a serial workflow uses one slot.', 1, 2, 10), ('Apply the native spend cap', 'src/agent.ts', 'maxBudgetUsd: limits.budgetUsd,', 'maxBudgetUsd bounds estimated spend for the query and child requests. It is not a prepaid currency reservation; a request can cross the threshold before the SDK stops.', 1, 2, 4), ('Preserve the launching environment', 'src/agent.ts', 'env: {', 'TypeScript env replaces the subprocess environment. Spread process.env, keep private credentials on the server, isolate settings, and append the explicit caps.', 1, 2, 9), ('Define a coordinator that can request a grandchild', 'src/agents.ts', 'coordinator: {', 'The coordinator declares Agent and Read. The runtime depth limit can remove Agent from the bottom layer; depth 1 and depth 2 produce different native trees.', 2, 3, 8), ('Detect actual direct and nested Agent calls', 'src/agent.ts', 'if (b.name === "Agent"', 'Retain all real Agent tool-use blocks, including nested delegations with a parent tool-use ID. A parent report alone does not prove a grandchild ran.', 2, 3, 5), ('Retain native tool refusal results', 'src/agent.ts', 'toolUseId: b.tool_use_id,', 'Record actual tool-return content and is_error. Concurrency refusal is a native result, not a host-invented simulation, and refused services remain unaudited.', 2, 1, 5), ('Handle the native budget result before the exception', 'src/agent.ts', 'status: message.subtype,', 'Retain result subtype, errors and estimated cost even when the SDK then raises. Budget mode expects error_max_budget_usd rather than treating it as a successful audit.', 2, 1, 8), ('Scope file access independently', 'src/policy.ts', 'if (name === "Read")', 'Permit only the three disposable service files and classroom instructions. Reviewers and workflow agents cannot edit source, execute shell commands or inspect .env.', 3, 4, 8), ('Launch the reviewed Workflow script', 'src/agent.ts', 'const script = workflowScript(c.mode);', 'The host supplies its fixed reviewed script through the native hook. Workflow is enabled in allowedTools, and repeat or unrelated launches are not approved.', 1, 2, 9), ('Declare native workflow metadata and inputs', 'workflows/audit-parallel.js', 'export const meta', 'A Workflow script begins with literal metadata, then a phase and fixed service inputs. The runtime provides agent and pipeline globals outside the parent conversation.', 2, 3, 7), ('Coordinate reviewers and return one result', 'workflows/audit-parallel.js', 'const audit =', 'Use agent for each read-only audit, pipeline to fan out over the list and script variables to retain intermediate reports. Return the consolidated result after completion.', 3, 4, 6), ('Independently verify fixture integrity', 'src/agent.ts', 'fixtureUnchanged: before.hash === after.hash,', 'Hash all three real service fixtures after the run. Native limits, observed child activity and unchanged files are separate pieces of evidence.', 1, 4, 5)]
document('/','Scale work. <em>Keep control.</em>','Bound a real service audit with depth, concurrency and spend caps, then coordinate it with Workflow.','<div class="flow"><div><b>01 · Configure</b><p>Depth, concurrency, spend</p></div><span>→</span><div><b>02 · Run</b><p>Agents or native Workflow</p></div><span>→</span><div><b>03 · Verify</b><p>Limits, lifecycle and reports</p></div></div><section class="panel" id="controls"><h2>Scale a bounded service audit</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Scaling experiment</label><select id="mode"><option value="bounded">Bounded audit · three service reviewers</option><option value="depth1">Depth 1 · no grandchildren</option><option value="depth2">Depth 2 · permit one nested auditor</option><option value="concurrency">Concurrency 1 · observe native refusals</option><option value="budget">Tiny budget · handle expected SDK stop</option><option value="opus">Opus 5 · custom delegation instruction</option><option value="preset">Opus 5 · claude_code preset and explicit task</option><option value="workflow">Workflow · bounded three-file fan-out</option><option value="serial">Workflow · sequential script coordination</option></select><button id="run" class="primary" disabled>Run scaling experiment →</button><p class="meta">Real SDK calls on three disposable service-policy files. Normal runs use a $0.80 SDK estimated spend cap. Budget intentionally uses $0.00001 to demonstrate error_max_budget_usd; a request may cross the estimate before stopping. Concurrency intentionally leaves refused services unaudited. No source edits or shell commands are permitted.</p></section><section class="step" id="picker-panel"><h2>Inspect an actual delegation</h2><p id="choice-status" class="note">Choose a direct Agent tool-use ID to inspect its nested telemetry. Workflow agents are identified through native lifecycle events instead.</p><label for="session-picker">Actual Agent tool-use IDs</label><select id="session-picker"><option>No delegations yet</option></select><button id="resume-session" style="display:none!important" hidden disabled>Resume selected session</button></section><section class="step" id="specialists-panel"><h2>Actual specialist activity</h2><div class="grid" id="specialists"></div><p>Native SubagentStart and SubagentStop events drive these cards. Native hooks show actual starts, stops and reports. Budget can stop before a child starts.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Host configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Each query and its actual agent definitions, tools and model options appear in the observation selector.</p></section></div><section class="step" id="comparison-panel"><h2>Actual parent responses</h2><div class="grid" id="branch-cards"></div></section><section class="step" id="results-panel"><h2>Actual results and parent session IDs</h2><div class="table"><table><thead><tr><th>Query</th><th>Stage</th><th>Status</th><th>session_id</th><th>Result text</th></tr></thead><tbody id="result-history"></tbody></table></div><pre class="json-view"><code id="latest-result" class="language-json">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Actual delegation catalog</h2><pre class="json-view"><code id="catalog" class="language-json">[]</code></pre></section><section class="step" id="messages-panel"><h2>Correlated child tools and reports</h2><pre class="json-view"><code id="messages" class="language-json">{}</code></pre><p>Direct Agent messages are correlated by parent_tool_use_id. Workflow child reads are observed through native PreToolUse hooks and completion reports; they are not all forwarded as assistant messages.</p></section><section class="step" id="storage-panel"><h2>Limits, native refusals and workflow evidence</h2><pre class="json-view"><code id="storage" class="language-json">{}</code></pre><p>Inspect actual caps, native lifecycle timing, hook-observed reads, budget stops and Workflow task events. Fixture hashes must remain unchanged.</p></section><section class="step" id="observation-panel"><h2>Inspect actual parent and specialist events</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand enforced caps, native limit evidence and script-based coordination.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. All experiments finish automatically. Budget stop and concurrency refusals are intentional teaching outcomes. Consume the entire stream for background Workflow completion. Change PORT if 3145 is occupied.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','SDK runtime','Children','Service files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 45 · Configure → delegate → enforce → consolidate</text>']
